    val HERO: Array<ULongArray> = Array(HERO_HEX.size) { m ->
        ULongArray(HERO_HEX[m].size) { r -> HERO_HEX[m][r].toULong(16) }
    }

    val HERO36: Array<ULongArray> = Array(HERO36_HEX.size) { m ->
        ULongArray(HERO36_HEX[m].size) { r -> HERO36_HEX[m][r].toULong(16) }
    }

    private fun mirrorRow(v: ULong, n: Int): ULong {
        var o = 0uL
        for (c in 0 until n) {
            if (((v shr (63 - c)) and 1uL) != 0uL) {
                o = o or (1uL shl (63 - (n - 1 - c)))
            }
        }
        return o
    }

    fun heroPose(
        src: ULongArray,
        n: Int,
        face: Int,
        state: Int,
        rawFrame: Int,
        hFace: Int
    ): ULongArray {
        val lookLeft = face == 3 || ((face == 0 || face == 2) && hFace == 3)
        val t = ULongArray(n) { r -> if (lookLeft) mirrorRow(src[r], n) else src[r] }
        var o = t.copyOf()

        fun flipUp() {
            if (face == 0) {
                for (i in 0 until n / 2) {
                    val tmp = o[i]
                    o[i] = o[n - 1 - i]
                    o[n - 1 - i] = tmp
                }
            }
        }

        val idleF = rawFrame and 3
        val frame = rawFrame and 1
        val legs = n - (n * 7) / 36

        if (state == 2 && frame == 1) {
            val m = (n * 14) / 36
            val top = (n * 8) / 36
            val span = n - top
            o = ULongArray(n)
            for (d in 0 until m) {
                val lo = top + (d * span) / m
                var hi = top + ((d + 1) * span) / m
                if (hi <= lo) hi = lo + 1
                var r = lo
                while (r < hi && r < n) {
                    o[n - m + d] = o[n - m + d] or t[r]
                    r++
                }
            }
            flipUp()
            return o
        }

        var k = 0
        var sway = 0
        if (state == 0) {
            val bl = intArrayOf(0, 1, 2, 1)
            val bs = intArrayOf(0, 1, 1, 0)
            k = if (n >= 30) bl[idleF] else bs[idleF]
            sway = if (idleF >= 2) 1 else 0
        }
        if (state == 2 && frame == 0) {
            k = if (n >= 30) 3 else 2
        }
        if (k > 0) {
            for (r in 0 until k) o[r] = 0uL
            for (r in k until legs) o[r] = t[r - k]
            for (r in (legs - k) until legs) o[legs] = o[legs] or t[r]
        }
        if (sway != 0) {
            val hr = (n * 19) / 36
            for (r in 0 until hr) {
                o[r] = if (lookLeft) (o[r] shl 1) else (o[r] shr 1)
            }
        }
        flipUp()
        return o
    }

    private val poseCache = LruCache<String, Bitmap>(256)
    private val simpleCache = LruCache<String, Bitmap>(64)

    fun getHeroBitmap(
        mask: Int,
        big: Boolean,
        face: Int,
        state: Int,
        frame: Int,
        hFace: Int,
        argbColor: Int
    ): Bitmap {
        val safeMask = mask.coerceIn(0, HERO.lastIndex)
        val key = "$safeMask|${if (big) 1 else 0}|$face|$state|$frame|$hFace|$argbColor"
        poseCache.get(key)?.let { return it }

        val n = if (big) 36 else 20
        val src = if (big) HERO36[safeMask] else HERO[safeMask]
        val rows = heroPose(src, n, face, state, frame, hFace)
        val pixels = IntArray(n * n)
        for (r in 0 until n) {
            val rowBits = rows[r]
            for (b in 0 until n) {
                if (((rowBits shr (63 - b)) and 1uL) != 0uL) {
                    pixels[r * n + b] = argbColor
                }
            }
        }
        val bmp = Bitmap.createBitmap(pixels, n, n, Bitmap.Config.ARGB_8888)
        poseCache.put(key, bmp)
        return bmp
    }

    fun getSimpleHeroBitmap(mask: Int, left: Boolean, argbColor: Int): Bitmap {
        val safeMask = mask.coerceIn(0, HERO.lastIndex)
        val key = "$safeMask|${if (left) 'L' else 'R'}|$argbColor"
        simpleCache.get(key)?.let { return it }

        val pixels = IntArray(20 * 20)
        for (r in 0 until 20) {
            val rowBits = HERO[safeMask][r]
            for (b in 0 until 20) {
                if (((rowBits shr (63 - b)) and 1uL) != 0uL) {
                    val colIdx = if (left) 19 - b else b
                    pixels[r * 20 + colIdx] = argbColor
                }
            }
        }
        val bmp = Bitmap.createBitmap(pixels, 20, 20, Bitmap.Config.ARGB_8888)
        simpleCache.put(key, bmp)
        return bmp
    }
